using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Security.Cryptography;using UnityEngine;
public static class AuditC127Export
{
 static int checks;static void Check(bool b,string m){checks++;if(!b)throw new Exception(m);}static string Hash(string p){using(var stream=File.OpenRead(p))using(var hash=SHA256.Create())return BitConverter.ToString(hash.ComputeHash(stream)).Replace("-","");}
 public static object Run(){checks=0;string root=(System.Environment.GetEnvironmentVariable("GUNMAGGEDON_ROOT") ?? throw new System.InvalidOperationException("Set GUNMAGGEDON_ROOT before running editor tools or fixtures."));string path=root+"/ModBuild/0.0.40/Gunmageddon_0.0.40.nobp";var bundle=AssetBundle.LoadFromFile(path);if(!bundle)throw new Exception("Export cannot be loaded");try{var names=bundle.GetAllAssetNames();Check(!names.Any(n=>n.Contains("_donotship")||n.Contains("blueprintersetupbackups")||n.Contains("gunmaggedonstaging")||n.EndsWith(".dll")||n.EndsWith(".cs")),"No raw private/proprietary dependencies or editor backups bundled");var manifest=bundle.LoadAsset<TextAsset>("assets/blueprinter/generated/patch_manifest.json");Check(manifest&&(string)Newtonsoft.Json.Linq.JObject.Parse(manifest.text)["modVersion"]=="0.0.40"&&((Newtonsoft.Json.Linq.JArray)Newtonsoft.Json.Linq.JObject.Parse(manifest.text)["Patches"]).Count>0,"Native references use the remap manifest");var units=new List<object>();int allGroups=0;foreach(var name in names.Where(n=>n.EndsWith(".prefab"))){var prefab=bundle.LoadAsset<GameObject>(name);if(!prefab)continue;foreach(var group in prefab.GetComponentsInChildren<LODGroup>(true)){var levels=group.GetLODs();var triangles=levels.Select(l=>l.renderers.Sum(r=>{Check(r,"LOD renderer survived export");var m=r.GetComponent<MeshFilter>().sharedMesh;long total=0;for(int i=0;i<m.subMeshCount;i++)total+=(long)m.GetIndexCount(i)/3;return total;})).ToArray();Check(group.enabled&&levels.Length>=3&&triangles[0]>triangles[1]&&triangles[1]>triangles[2],"Export retains meaningful LOD reductions: "+prefab.name);allGroups++;}
   if(!name.Contains("/c127/")||!name.EndsWith("_emplacement.prefab"))continue;var unit=prefab.GetComponent<Building>();Check(unit&&unit.definition&&unit.definition.jsonKey.StartsWith("Gunmaggedon_C127",StringComparison.Ordinal),"New native unit definition survives export");Check(unit.definition.unitPrefab==prefab,"Definition resolves its exported prefab");Check(prefab.GetComponentsInChildren<Collider>(true).All(c=>c.GetComponent<UnitPart>()&&c.GetComponent<UnitPart>().parentUnit==unit),"Exported collision ownership");var groups=prefab.GetComponentsInChildren<LODGroup>(true);var renderers=prefab.GetComponentsInChildren<MeshRenderer>(true);Check(renderers.All(r=>groups.Any(g=>g.GetLODs().Any(l=>l.renderers.Contains(r)))),"All physical renderers accounted for after export");var guns=prefab.GetComponentsInChildren<Gun>(true);bool twin=unit.definition.jsonKey=="Gunmaggedon_C127T";Check(guns.Length==(twin||unit.definition.jsonKey=="Gunmaggedon_C127C"?2:1),"Expected combat barrel count");foreach(var gun in guns){Check(gun.enabled&&!gun.Safety&&gun.info&&gun.info.name==(twin?"C127_Twin_Weapon":"C127_Surface_Weapon"),"Correct exported weapon role");Check(gun.info.targetRequirements.maxRange==12000&&gun.info.blastDamage==4.5f,"Exported ballistic profile");}var bunker=prefab.transform.Find("BunkerStructure");Check(bunker?bunker.GetComponent<MeshCollider>()!=null:prefab.transform.Find("ConcreteBase")!=null,"Concrete support/openings survive export");units.Add(new{unit=unit.definition.unitName,guns=guns.Length,colliders=prefab.GetComponentsInChildren<Collider>(true).Length});}
   Check(units.Count==5,"Exactly five C127 units");var audio=names.Where(n=>bundle.LoadAsset<AudioClip>(n)).ToArray();Check(names.Where(n=>n.EndsWith(".mp3")).All(n=>bundle.LoadAsset<AudioClip>(n)&&!bundle.LoadAsset<TextAsset>(n)),"MP3 asset labels represent imported AudioClips, not raw file payloads");Check(audio.Length==9,"Existing nine custom clips retained; no native audio copied");var report=new{passed=true,checks,assets=names.Length,allGroups,units,audioClips=audio.Length,pack="0.0.40",packSha256=Hash(path),runtime="1.22.0",runtimeSha256=Hash(root+"/GunmaggedonRuntime/build/1.22.0/Gunmaggedon.Runtime.dll")};string json=Newtonsoft.Json.JsonConvert.SerializeObject(report);Directory.CreateDirectory(root+"/GunmaggedonRuntime/build/c127-combat");File.WriteAllText(root+"/GunmaggedonRuntime/build/c127-combat/export-audit.json",json);return json;
 }finally{bundle.Unload(true);}}
